import { headers } from 'next/headers';

// Async server component: fetches user-specific data at request time.
// Parent wraps in Suspense for streaming. No 'use cache' - data changes per request.
export default async function UserDashboard() {
  const headersList = await headers();
  const host = headersList.get('x-forwarded-host') ?? headersList.get('host') ?? 'localhost:3000';
  const protocol = headersList.get('x-forwarded-proto') ?? 'http';
  const baseUrl = `${protocol}://${host}`;

  const res = await fetch(`${baseUrl}/api/user/preferences`, {
    cache: 'no-store',
  });
  const preferences = await res.json();

  return (
    <div>
      <h2>User Dashboard</h2>
      <p>User preferences: {JSON.stringify(preferences)}</p>
    </div>
  );
}

